from pathlib import Path

index_path = Path('index.html')
css_path = Path('overrides.css')
html = index_path.read_text(encoding='utf-8')
css = css_path.read_text(encoding='utf-8')

profile_b64 = ""

profile_html = (
    '<a class="nav-profile-link" href="https://www.linkedin.com/in/ramez-medhat-rvu/" '
    'target="_blank" rel="noopener noreferrer" aria-label="Ramez Medhat LinkedIn profile">'
    f'<img src="data:image/webp;base64,{profile_b64}" alt="Ramez Medhat"></a>'
)

if 'class="nav-profile-link"' not in html:
    anchor = '<div class="nav-actions">'
    if anchor not in html:
        raise RuntimeError('nav-actions anchor not found')
    html = html.replace(anchor, profile_html + anchor, 1)

marker = '/* about-proof-nav-v1 */'
if marker in css:
    css = css.split(marker, 1)[0].rstrip() + '\n'

css += '''\n/* about-proof-nav-v1 */\n.hunt-proof-grid{grid-template-columns:repeat(2,minmax(0,1fr))!important;gap:18px!important;align-items:stretch}.hunt-proof-grid .proof-card-combined,.hunt-proof-grid .proof-card-wide{grid-column:span 1!important;width:100%;min-height:0!important;padding:22px 24px!important}.hunt-proof-grid .proof-card-combined{display:grid!important;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px;align-items:start}.hunt-proof-grid .proof-card-combined .proof-combined-part{margin:0!important;padding:0!important;border:0!important}.hunt-proof-grid .proof-card-combined .proof-combined-part+.proof-combined-part{padding-inline-start:20px!important;border-inline-start:1px solid rgba(255,255,255,.11)!important}.hunt-proof-grid .proof-card-combined b,.hunt-proof-grid .proof-card-wide>b{font-size:clamp(1rem,1.5vw,1.28rem)!important;line-height:1.25!important;margin-bottom:8px!important}.hunt-proof-grid .proof-card-combined p,.hunt-proof-grid .proof-card-wide>p{font-size:.87rem!important;line-height:1.7!important;margin:0!important}.hunt-proof-grid .proof-card-wide .offline-camp-lines{grid-template-columns:repeat(3,minmax(0,1fr))!important;gap:9px!important;margin-top:14px!important}.hunt-proof-grid .proof-card-wide .offline-camp-line{min-height:46px!important;padding:8px 10px!important;font-size:.76rem!important;line-height:1.35!important}.nav{overflow:visible!important}.nav .container,.nav-inner{overflow:visible!important}.nav-inner{position:relative!important}.nav-profile-link{position:absolute;left:4px;top:50%;transform:translateY(-50%);z-index:20;width:96px;height:96px;border-radius:50%;padding:4px;background:linear-gradient(145deg,rgba(249,115,22,.95),rgba(96,165,250,.8));box-shadow:0 0 0 3px rgba(7,7,7,.92),0 10px 28px rgba(0,0,0,.48),0 0 24px rgba(249,115,22,.16);transition:transform .2s ease,box-shadow .2s ease}.nav-profile-link:hover{transform:translateY(-50%) scale(1.04);box-shadow:0 0 0 3px rgba(7,7,7,.92),0 12px 30px rgba(0,0,0,.55),0 0 30px rgba(249,115,22,.24)}.nav-profile-link img{display:block;width:100%;height:100%;object-fit:cover;object-position:center 38%;border-radius:50%;border:2px solid #0b0b0b}.nav-actions{margin-left:112px!important}.nav-linkedin{display:none!important}@media(max-width:980px){.hunt-proof-grid{grid-template-columns:1fr!important}.hunt-proof-grid .proof-card-combined,.hunt-proof-grid .proof-card-wide{grid-column:span 1!important}.nav-profile-link{width:78px;height:78px;left:8px}.nav-actions{margin-left:92px!important}}@media(max-width:700px){.hunt-proof-grid .proof-card-combined{grid-template-columns:1fr!important;gap:14px}.hunt-proof-grid .proof-card-combined .proof-combined-part+.proof-combined-part{padding-inline-start:0!important;padding-top:14px!important;border-inline-start:0!important;border-top:1px solid rgba(255,255,255,.1)!important}.hunt-proof-grid .proof-card-wide .offline-camp-lines{grid-template-columns:1fr!important}.nav-profile-link{width:60px;height:60px;left:8px;padding:3px}.nav-actions{margin-left:68px!important}}@media(max-width:420px){.nav-profile-link{width:52px;height:52px;left:6px}.nav-actions{margin-left:58px!important}}\n'''

index_path.write_text(html, encoding='utf-8')
css_path.write_text(css, encoding='utf-8')
print('About proof cards widened and navbar profile photo added.')
